script:
frappe.ui.form.on("Employee", {
	refresh(frm) {
		const field = frm.fields_dict.start_offboarding;
		if (!field || frm.doc.status === "Left" || frm.is_new()) return;

		frappe.db.get_value("Employee Separation", { employee: frm.doc.name }, "name").then(({ message }) => {
			frm._offboarding_separation = (message && message.name) || null;
			field.set_df_property("label", frm._offboarding_separation ? __("Offboarding Started") : __("Start Offboarding"));
		});
	},

	start_offboarding(frm) {
		if (frm._offboarding_separation) {
			frappe.show_alert({
				message: __("Offboarding was already started for {0}.", [frm.doc.employee_name]),
				indicator: "blue",
			});
			return;
		}

		frappe.prompt(
			[
				{
					fieldname: "relieving_date",
					fieldtype: "Date",
					label: __("Relieving Date"),
					reqd: 1,
					default: frm.doc.relieving_date || frappe.datetime.get_today(),
				},
			],
			(values) => {
				frappe.call({
					method: "frappe.client.set_value",
					args: {
						doctype: "Employee",
						name: frm.doc.name,
						fieldname: "relieving_date",
						value: values.relieving_date,
					},
					freeze: true,
					freeze_message: __("Starting offboarding…"),
					callback() {
						frappe.call({
							method: "frappe.client.insert",
							args: {
								doc: {
									doctype: "Employee Separation",
									employee: frm.doc.name,
									boarding_begins_on: frappe.datetime.get_today(),
								},
							},
							callback(r) {
								if (!r.message) return;
								frm._offboarding_separation = r.message.name;
								frm.fields_dict.start_offboarding.set_df_property("label", __("Offboarding Started"));
								frappe.show_alert({
									message: __("Offboarding started for {0}.", [frm.doc.employee_name]),
									indicator: "green",
								});
								frm.reload_doc();
							},
						});
					},
				});
			},
			__("Set Relieving Date"),
			__("Start Offboarding")
		);
	},
});
